import type { MetadataRoute } from "next";

// Web app manifest: makes the browser offer "Install app" (no service worker on purpose - data always comes from Drive).
// Icons are generated by scripts/generate-pwa-icons.cjs.
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: "BikeVault – Garáž a servis kol",
    short_name: "BikeVault",
    description: "Garáž, komponenty a servis kol na jednom místě, data v soukromém Google Disku.",
    lang: "cs",
    start_url: "/garage",
    scope: "/",
    display: "standalone",
    background_color: "#f4f5f6",
    theme_color: "#0f1113",
    icons: [
      { src: "/icon-192.png", sizes: "192x192", type: "image/png", purpose: "any" },
      { src: "/icon-512.png", sizes: "512x512", type: "image/png", purpose: "any" },
      { src: "/icon-maskable-512.png", sizes: "512x512", type: "image/png", purpose: "maskable" },
    ],
  };
}
